	/**
	 * The UTS-46 hostname reading of $s: every code point in MAP replaced by
	 * its target. Byte-safe: strtr() matches each key — one whole code point,
	 * a lead byte then continuation bytes — only at a code point's start,
	 * also inside text that is not valid UTF-8. Returns $s itself when no
	 * key's first byte occurs in it (LEAD) — Hebrew and Arabic prose never
	 * pay for the 1526-key strtr().
	 *
	 * @param string $s Text.
	 * @return string
	 */
	public static function map( $s ) {
		if ( strlen( $s ) === strcspn( $s, self::LEAD ) ) {
			return $s;
		}
		return strtr( $s, self::MAP );
	}
